def analyze(root,p):
    cells={};all_rows=[]
    for task in p['study_issue_order']:
        for arm in ('none','ours'):
            rows=attempts(root,task,arm);native=[r for r in rows if r.get('native_started')];all_rows+=native;last=rows[-1] if rows else {};known=bool(last and valid(last));cost=sum(r.get('stream',{}).get('token_volume_lower_bound',0) for r in native);proxy=sum(r.get('stream',{}).get('cache_adjusted_volume_5m_proxy',0) for r in native)
            complete=bool(native) and all(r.get('stream',{}).get('usage_complete',False) for r in native)
            cells[task,arm]=dict(task=task,arm=arm,admitted=bool(native),native_attempts=len(native),outcome_known=known,solved=last['solved'] if known else None,all_attempt_token_volume=cost,all_attempt_cache_proxy=proxy,usage_complete=complete,attempts=[dict(attempt=r['attempt'],allowance_commit=r.get('allowance_commit'),provider_models=r.get('stream',{}).get('main_provider_model_ids',[]),usage_complete=r.get('stream',{}).get('usage_complete',False),per_model=r.get('stream',{}).get('per_model'),totals=r.get('stream',{}).get('totals'),native_wall_seconds=r.get('wall_seconds'),grade_valid=r.get('grade_valid',False),solved=r.get('solved'),plugins=r.get('verified_plugins'),expansion_verified=r.get('expansion',{}).get('command_expansion_verified'),quota_before=r.get('quota_before'),quota_after=r.get('quota_after'),native_sha256=r.get('native_sha256'),context_sha256=r.get('context_sha256'),prompt_sha256=r.get('prompt_sha256'),patch_sha256=r.get('patch_sha256'),grade_sha256=r.get('grade_sha256'),error=r.get('error')) for r in native])
