        result.update(paired_solve_difference=float(delta.mean()),paired_bootstrap_95_ci=np.quantile(draws,[.025,.975],method='linear').tolist(),exact_mcnemar_p=min(1.,2*sum(math.comb(d,k) for k in range(min(b,c)+1))/2**d) if d else 1.,discordant_counts=dict(ours_only=b,none_only=c))
        eligible=all(cells[t,a]['usage_complete'] for t in pairs for a in ('none','ours'));result['paired_cost_usage_complete']=eligible
